head.script:
scwin.trigger3_onclick = function(e) {
	var rowJSON = {
		"addr": "서울시",
		"name": "손예진",
		"rowStatus": "R"
	};
	var dataObject = {
		type: "json",
		data: rowJSON,
		name: "rowObj"
	};
	var options = {
		type: "browserPopup",
		id: "테스트팝업",
		width: "800px",
		height: "500px",
		modal: true,
		useControl: true,
		controls: {
			minimize: true,
			maximize: true,
			close: false
		},
		dataObject: dataObject
	};
	$p.openPopup("/sample/common_link/p_popup_openPopup_getParameter_WESE-282_(WSQ-5274)_popup.xml", options);
};
